"""Audio I/O and processing utilities.

Provides functions for loading, resampling, silence removal, chunking,
cross-fading, and format conversion. Used by ``OmniVoice.generate()`` during
inference post-processing.
"""

import numpy as np
import torch
import torchaudio
import soundfile as sf


def load_audio(audio_path: str, sampling_rate: int):
    """
    Load the waveform with SoundFile and resample if needed.

    Parameters:
        audio_path: path of the audio.
        sampling_rate: target sampling rate.

    Returns:
        Loaded prompt waveform with target sampling rate,
        PyTorch tensor of shape (1, T)
    """
    audio_data, prompt_sampling_rate = sf.read(audio_path, dtype="float32")
    if audio_data.ndim == 1:
        waveform = torch.from_numpy(audio_data).unsqueeze(0)
    else:
        waveform = torch.from_numpy(audio_data.T)

    if prompt_sampling_rate != sampling_rate:
        waveform = torchaudio.functional.resample(
            waveform,
            orig_freq=prompt_sampling_rate,
            new_freq=sampling_rate,
        )
    if waveform.shape[0] > 1:
        waveform = torch.mean(waveform, dim=0, keepdim=True)

    return waveform


# ── Silence detection (pure torch/numpy) ─────────────────────────────────────

def _rms_db(audio: torch.Tensor, frame_size: int, hop_size: int) -> torch.Tensor:
    """Compute RMS energy in dB for overlapping frames."""
    mono = audio.mean(0) if audio.dim() > 1 else audio
    # Pad to ensure we cover the full signal
    pad_len = frame_size - (mono.shape[0] % hop_size or hop_size)
    if pad_len > 0:
        mono = torch.nn.functional.pad(mono, (0, pad_len))
    frames = mono.unfold(0, frame_size, hop_size)
    rms = (frames ** 2).mean(-1).sqrt().clamp(min=1e-10)
    return 20 * torch.log10(rms)


def _detect_nonsilent_ranges(
    audio: torch.Tensor,
    sample_rate: int,
    min_silence_len_ms: int = 300,
    silence_thresh_db: float = -50.0,
    seek_step_ms: int = 10,
):
    """Return list of (start_sample, end_sample) for non-silent regions."""
    hop = int(sample_rate * seek_step_ms / 1000)
    frame_size = hop  # one frame per hop
    db = _rms_db(audio, frame_size, hop)

    is_silent = db < silence_thresh_db
    min_silent_frames = max(1, int(min_silence_len_ms / seek_step_ms))

    # Find non-silent regions
    ranges = []
    in_speech = False
    speech_start = 0
    silent_count = 0

    for i, s in enumerate(is_silent):
        if not s:
            if not in_speech:
                speech_start = i
                in_speech = True
            silent_count = 0
        else:
            if in_speech:
                silent_count += 1
                if silent_count >= min_silent_frames:
                    end = i - min_silent_frames + 1
                    ranges.append((speech_start * hop, end * hop))
                    in_speech = False
                    silent_count = 0

    if in_speech:
        ranges.append((speech_start * hop, audio.shape[-1]))

    return ranges


def _detect_leading_silence_samples(
    audio: torch.Tensor,
    sample_rate: int,
    silence_thresh_db: float = -50.0,
    seek_step_ms: int = 10,
) -> int:
    """Return number of silent samples at the start of audio."""
    hop = int(sample_rate * seek_step_ms / 1000)
    db = _rms_db(audio, hop, hop)
    for i, val in enumerate(db):
        if val >= silence_thresh_db:
            return i * hop
    return audio.shape[-1]


# ── Public API ────────────────────────────────────────────────────────────────

def remove_silence(
    audio: torch.Tensor,
    sampling_rate: int,
    mid_sil: int = 300,
    lead_sil: int = 100,
    trail_sil: int = 300,
):
    """
    Remove middle silences longer than mid_sil ms, and edge silences longer than edge_sil ms

    Parameters:
        audio: PyTorch tensor with shape (C, T).
        sampling_rate: sampling rate of the audio.
        mid_sil: the duration of silences in the middle of audio to be removed in ms.
            if mid_sil <= 0, no middle silence will be removed.
        lead_sil: the duration of kept leading silence in ms.
        trail_sil: the duration of added trailing silence in ms.

    Returns:
        PyTorch tensor with shape (C, T), where C is number of channels
            and T is number of audio samples
    """
    mono = audio.mean(0) if audio.dim() > 1 and audio.shape[0] > 1 else audio.squeeze(0)

    if mid_sil > 0:
        ranges = _detect_nonsilent_ranges(
            mono, sampling_rate,
            min_silence_len_ms=mid_sil,
            silence_thresh_db=-50.0,
            seek_step_ms=10,
        )
        if ranges:
            # Keep mid_sil/2 of silence on each side of non-silent regions
            keep_samples = int(sampling_rate * mid_sil / 2000)
            parts = []
            for start, end in ranges:
                s = max(0, start - keep_samples)
                e = min(audio.shape[-1], end + keep_samples)
                parts.append(audio[..., s:e])
            audio = torch.cat(parts, dim=-1)
            mono = audio.mean(0) if audio.dim() > 1 and audio.shape[0] > 1 else audio.squeeze(0)

    # Remove leading silence
    lead_samples = _detect_leading_silence_samples(mono, sampling_rate, -50.0, 10)
    keep_lead = int(sampling_rate * lead_sil / 1000)
    trim_start = max(0, lead_samples - keep_lead)
    audio = audio[..., trim_start:]

    # Remove trailing silence
    mono_rev = mono.flip(0)
    trail_silent = _detect_leading_silence_samples(mono_rev, sampling_rate, -50.0, 10)
    keep_trail = int(sampling_rate * trail_sil / 1000)
    trim_end = max(0, trail_silent - keep_trail)
    if trim_end > 0:
        audio = audio[..., :audio.shape[-1] - trim_end]

    return audio


def trim_leading_silence(
    audio: torch.Tensor,
    sample_rate: int = 24000,
    skip_ms: float = 100.0,
    threshold_db: float = -40.0,
    fade_ms: float = 10.0,
) -> torch.Tensor:
    """Trim silence from the start of audio, ignoring initial noise.

    Skips the first ``skip_ms`` milliseconds (which may contain low-level
    codec noise), then finds the first sample above ``threshold_db`` and
    trims everything before it. Applies a short fade-in to avoid clicks.

    Args:
        audio: Tensor of shape (C, T).
        sample_rate: Sample rate in Hz.
        skip_ms: Ignore this many ms at the start when scanning for silence.
        threshold_db: Amplitude threshold in dB (relative to peak) for
            detecting voice onset.
        fade_ms: Duration of fade-in after trim in ms.

    Returns:
        Trimmed tensor of shape (C, T_trimmed).
    """
    if audio.shape[-1] == 0:
        return audio

    skip_samples = int(skip_ms / 1000.0 * sample_rate)
    fade_samples = int(fade_ms / 1000.0 * sample_rate)

    # Work with mono amplitude for detection
    mono = audio.abs().mean(dim=0)
    peak = mono.max()
    if peak < 1e-8:
        return audio

    threshold = peak * (10 ** (threshold_db / 20.0))

    # Scan from skip_samples onward for first sample above threshold
    search_region = mono[skip_samples:]
    above = (search_region > threshold).nonzero(as_tuple=False)

    if len(above) == 0:
        return audio  # no voice found, return as-is

    trim_point = skip_samples + above[0].item()

    # Trim
    audio = audio[..., trim_point:]

    # Fade in
    if fade_samples > 0 and audio.shape[-1] > fade_samples:
        fade_in = torch.linspace(0, 1, fade_samples, device=audio.device, dtype=audio.dtype)
        audio[..., :fade_samples] = audio[..., :fade_samples] * fade_in

    return audio


def fade_and_pad_audio(
    audio: torch.Tensor,
    pad_duration: float = 0.1,
    fade_duration: float = 0.1,
    sample_rate: int = 24000,
) -> torch.Tensor:
    """
    Applies a smooth fade-in and fade-out to the audio, and then pads both sides
    with pure silence to prevent abrupt starts and ends (clicks/pops).

    Args:
        audio: PyTorch tensor of shape (C, T) containing audio data.
        pad_duration: Duration of pure silence to add to each end (in seconds).
        fade_duration: Duration of the fade-in/out curve (in seconds).
        sample_rate: Audio sampling rate.

    Returns:
        Processed sequence tensor with shape (C, T_new)
    """
    if audio.shape[-1] == 0:
        return audio

    fade_samples = int(fade_duration * sample_rate)
    pad_samples = int(pad_duration * sample_rate)

    processed = audio.clone()

    if fade_samples > 0:
        k = min(fade_samples, processed.shape[-1] // 2)

        if k > 0:
            fade_in = torch.linspace(
                0, 1, k, device=processed.device, dtype=processed.dtype
            )[None, :]
            processed[..., :k] = processed[..., :k] * fade_in

            fade_out = torch.linspace(
                1, 0, k, device=processed.device, dtype=processed.dtype
            )[None, :]
            processed[..., -k:] = processed[..., -k:] * fade_out

    if pad_samples > 0:
        silence = torch.zeros(
            (processed.shape[0], pad_samples),
            dtype=processed.dtype,
            device=processed.device,
        )
        processed = torch.cat([silence, processed, silence], dim=-1)

    return processed


def trim_long_audio(
    audio: torch.Tensor,
    sampling_rate: int,
    max_duration: float = 15.0,
    min_duration: float = 3.0,
    trim_threshold: float = 20.0,
) -> torch.Tensor:
    """Trim audio to <= max_duration by splitting at the largest silence gap.

    Only trims when the audio exceeds *trim_threshold* seconds.

    Args:
        audio: Audio tensor of shape (C, T).
        sampling_rate: Audio sampling rate.
        max_duration: Maximum duration in seconds.
        min_duration: Minimum duration in seconds.
        trim_threshold: Only trim if audio is longer than this (seconds).

    Returns:
        Trimmed audio tensor.
    """
    duration = audio.size(-1) / sampling_rate
    if duration <= trim_threshold:
        return audio

    mono = audio.mean(0) if audio.dim() > 1 and audio.shape[0] > 1 else audio.squeeze(0)
    ranges = _detect_nonsilent_ranges(
        mono, sampling_rate,
        min_silence_len_ms=100,
        silence_thresh_db=-40.0,
        seek_step_ms=10,
    )
    if not ranges:
        return audio

    max_samples = int(max_duration * sampling_rate)
    min_samples = int(min_duration * sampling_rate)

    # Walk through speech regions; at each gap pick the latest split <= max_duration
    best_split = 0
    for start, end in ranges:
        if start > best_split and start <= max_samples:
            best_split = start
        if end > max_samples:
            break

    if best_split < min_samples:
        best_split = min(max_samples, audio.shape[-1])

    return audio[..., :best_split]


def cross_fade_chunks(
    chunks: list[torch.Tensor],
    sample_rate: int,
    silence_duration: float = 0.3,
) -> torch.Tensor:
    """Concatenate audio chunks with a short silence gap and fade at boundaries.

    Each boundary is structured as: fade-out tail → silence buffer → fade-in head.
    This avoids click artifacts from direct concatenation or overlapping mismatch.

    Args:
        chunks: List of audio tensors, each (C, T).
        sample_rate: Audio sample rate.
        silence_duration: Total silence gap duration in seconds.

    Returns:
        Merged audio tensor (C, T_total).
    """
    if len(chunks) == 1:
        return chunks[0]

    total_n = int(silence_duration * sample_rate)
    fade_n = total_n // 3
    silence_n = fade_n  # middle silent gap
    merged = chunks[0].clone()

    for chunk in chunks[1:]:
        dev, dt = merged.device, merged.dtype
        parts = [merged]

        # Fade out tail of current merged audio
        fout_n = min(fade_n, merged.size(-1))
        if fout_n > 0:
            w_out = torch.linspace(1, 0, fout_n, device=dev, dtype=dt)[None, :]
            parts[-1][..., -fout_n:] = parts[-1][..., -fout_n:] * w_out

        # Silent buffer between chunks
        parts.append(torch.zeros(chunks[0].shape[0], silence_n, device=dev, dtype=dt))

        # Fade in head of next chunk
        fade_in = chunk.clone()
        fin_n = min(fade_n, fade_in.size(-1))
        if fin_n > 0:
            w_in = torch.linspace(0, 1, fin_n, device=dev, dtype=dt)[None, :]
            fade_in[..., :fin_n] = fade_in[..., :fin_n] * w_in

        parts.append(fade_in)
        merged = torch.cat(parts, dim=-1)

    return merged
